// batch77: derivedImpl + derived — data-driven from batch77_truth.json (truth
// generated by Node vm against the real TS derivedImpl.ts/derived.ts plus real
// baseObservable/observableValue/autorunImpl/autorun).
import 'dart:convert';
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/base.dart'
    show IObservableWithChange, IReader;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/changeTracker.dart'
    show IChangeContext, IChangeTracker;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/observables/derived.dart'
    as d;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/observables/observableValue.dart'
    as ov;
import 'package:semi_design_flutter/src/monaco/base/common/observableInternal/reactions/autorun.dart'
    as au;
import 'package:semi_design_flutter/src/monaco/base/common/lifecycle.dart'
    show IDisposable, toDisposable;

Map<String, dynamic> _truth() => jsonDecode(
      File('tool/ts2dart/batch77_truth.json').readAsStringSync(),
    ) as Map<String, dynamic>;

/// 1:1: the change tracker used in the truth script for derivedHandleChanges.
class _HCSummary {
  int base = 0;
  final List<Object?> deltas = <Object?>[];
}

void main() {
  group('batch77 derived', () {
    test('no observers: recompute on every get, no caching', () {
      final t = _truth()['noObservers'] as Map<String, dynamic>;
      final src = ov.observableValue<int, Object?>('src', 1);
      int count = 0;
      final derived = d.derived<int, Object?>((reader) {
        count++;
        return reader.readObservable(src) * 2;
      });
      final g1 = derived.get();
      final g2 = derived.get();
      expect(g1, t['g1']);
      expect(g2, t['g2']);
      expect(count, t['count']);
      expect((derived as dynamic).debugGetState()['stateStr'], t['stateStr']);
    });

    test('with autorun: cached, recompute on source change', () {
      final t = (_truth()['withAutorun'] as Map<String, dynamic>);
      final src = ov.observableValue<int, Object?>('src2', 1);
      int recomputes = 0;
      final derived = d.derived<int, Object?>((reader) {
        recomputes++;
        return reader.readObservable(src) * 10;
      });
      final seen = <int>[];
      final disposable = au.autorun((reader) {
        seen.add(derived.read(reader));
      });

      final afterInit = t['afterInit'] as Map<String, dynamic>;
      expect(seen, afterInit['seen']);
      expect(recomputes, afterInit['recomputes']);
      expect((derived as dynamic).debugGetState()['stateStr'],
          afterInit['stateStr']);

      src.set(2, null, null);
      final afterSet = t['afterSet'] as Map<String, dynamic>;
      expect(seen, afterSet['seen']);
      expect(recomputes, afterSet['recomputes']);
      expect((derived as dynamic).debugGetState()['stateStr'],
          afterSet['stateStr']);

      src.set(2, null, null); // equal value -> ObservableValue.set returns early
      final afterEqual = t['afterEqualSet'] as Map<String, dynamic>;
      expect(seen, afterEqual['seen']);
      expect(recomputes, afterEqual['recomputes']);

      disposable.dispose();
      final afterDispose = t['afterDispose'] as Map<String, dynamic>;
      expect((derived as dynamic).debugGetState()['stateStr'],
          afterDispose['stateStr']);
      expect((derived as dynamic).debugGetObservers().length,
          afterDispose['observerCount']);
    });

    test('derivedOpts: equalsFn + onLastObserverRemoved', () {
      final t = _truth()['derivedOpts'] as Map<String, dynamic>;
      final src = ov.observableValue<int, Object?>('src3', 1);
      int removed = 0;
      final derived = d.derivedOpts<int>(
        d.DerivedOpts<int>(
          debugName: 'eq',
          equalsFn: (a, b) => (a - b).abs() < 3,
          onLastObserverRemoved: () => removed++,
        ),
        (reader) => reader.readObservable(src),
      );
      final seen = <int>[];
      final disposable = au.autorun((reader) => seen.add(derived.read(reader)));

      src.set(2, null, null); // |2-1|<3 -> considered equal
      expect(seen, t['afterSmall']);
      src.set(9, null, null); // |9-2|>=3 -> change
      expect(seen, t['afterBig']);
      disposable.dispose();
      expect(removed, t['removed']);
    });

    test('derivedWithSetter: set drives external setter', () {
      final t = _truth()['derivedWithSetter'] as Map<String, dynamic>;
      final src = ov.observableValue<int, Object?>('src4', 5);
      int external = 100;
      final derived = d.derivedWithSetter<int>(
        null,
        (reader) => reader.readObservable(src) + 1,
        (value, tx) => external = value,
      );
      expect(derived.get(), t['initial']);
      derived.set(42, null, null);
      expect(external, t['externalAfterSet']);
    });

    test('derivedHandleChanges: changeTracker collects deltas', () {
      final t = _truth()['derivedHandleChanges'] as Map<String, dynamic>;
      final src = ov.observableValue<int, Object?>('src5', 0);

      final tracker = _HCTracker(src);
      final seen = <Map<String, Object?>>[];
      final derived = d.derivedHandleChanges<int, Object?, _HCSummary>(
        d.DerivedHandleChangesOpts<_HCSummary, int>(
          debugName: 'hc',
          changeTracker: tracker,
        ),
        (reader, summary) {
          seen.add(<String, Object?>{
            'base': summary.base,
            'deltas': summary.deltas.toList(),
          });
          return reader.readObservable(src) + summary.deltas.length;
        },
      );
      final disposable = au.autorun((reader) => derived.read(reader));
      src.set(7, null, 'D7');
      src.set(8, null, 'D8');
      disposable.dispose();
      expect(seen, t['seen']);
    });

    test('derivedWithStore: store cleared on recompute, disposed on no observers',
        () {
      final t = _truth()['derivedWithStore'] as Map<String, dynamic>;
      final src = ov.observableValue<int, Object?>('src6', 1);
      final stores = <Object>[];
      final derived = d.derivedWithStore<int>((reader, store) {
        stores.add(store);
        (store as dynamic).add(toDisposable(() {}));
        return reader.readObservable(src);
      });
      final disposable = au.autorun((reader) => derived.read(reader));
      final first = stores[0];
      src.set(2, null, null);
      final second = stores[1];
      expect(stores.length, t['storeCount']);
      expect(identical(first, second), t['sameWhileObserved']);
      expect((first as dynamic).isDisposed, t['firstDisposedAfterClear']);
      disposable.dispose();
      expect((second as dynamic).isDisposed,
          t['lastDisposedAfterNoObservers']);
    });

    test('derivedDisposable: disposes old value on recompute and on removal', () {
      final t = _truth()['derivedDisposable'] as Map<String, dynamic>;
      final src = ov.observableValue<int, Object?>('src7', 1);
      int disposedFlag = 0;
      final derived = d.derivedDisposable<Object?>((reader) {
        reader.readObservable(src);
        return _Disp(() => disposedFlag++);
      });
      final disposable = au.autorun((reader) => derived.read(reader));
      expect(disposedFlag, t['before']);
      src.set(2, null, null);
      expect(disposedFlag, t['afterRecompute']);
      disposable.dispose();
      expect(disposedFlag, t['afterNoObservers']);
    });
  });
}

class _Disp implements IDisposable {
  _Disp(this._fn);
  final void Function() _fn;
  @override
  void dispose() => _fn();
}

class _HCTracker implements IChangeTracker<_HCSummary> {
  _HCTracker(this.src);
  final IObservableWithChange<int, Object?> src;

  @override
  _HCSummary createChangeSummary(_HCSummary? previous) => _HCSummary();

  @override
  void beforeUpdate(IReader reader, _HCSummary change) {
    change.base = reader.readObservable(src);
  }

  @override
  bool handleChange(IChangeContext ctx, _HCSummary change) {
    if (ctx.didChange(src)) {
      change.deltas.add(ctx.change);
    }
    return true;
  }
}
